import concurrent.futures, urllib.request, pathlib
covers = {'creative-act':'9780593652886','midnight-library':'9780525559474','mountain-is-you':'9781949759228','little-life':'9780804172707','atomic-habits':'9780735211292','alchemist':'9780061122415','normal-people':'9781984822185','educated':'9780399590504'}
def download(item):
 name,isbn=item
 try:
  data=urllib.request.urlopen(f'https://covers.openlibrary.org/b/isbn/{isbn}-L.jpg',timeout=25).read()
  pathlib.Path(f'public/covers/{name}.jpg').write_bytes(data)
  return name,len(data)
 except Exception as e: return name,str(e)
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
 for result in pool.map(download,covers.items()): print(result)
